    int left = 0;
    // 右索引的初始值是数组中元素的数量
    int right = nums.length;
    // left + 1 >= right 将完成 while 循环
    while (left + 1 < right) {
      int mid = (right + left) / 2;

      if (nums[mid] == mid && left < nums[left]) {
        // mid 是要回答的索引
        return mid;
      } else if (nums[mid] < mid) {
        // 在数组的左半部分搜索是没有意义的
        left = mid;
      } else {
        // 在数组的右半部分搜索没有意义
        right = mid;
      }
    }
    // left 可以是答案的索引  
    if (nums[left] == left) {
      return left;
    }
    // right 可能是寻找的索引
    if (right < nums.length && nums[right] == right) {
      return right;
    }
    // 数组中没有与其索引相等的项
    return -1;
  }

  public static void main(String[] args) {
    Solution sol = new Solution();
    int[] nums1 = new int[] {1, 5, 8, 9, 11, 13, 15, 19, 21};
    int[] nums2 = new int[] {-8, -2, -1, 0, 2, 5, 8, 9};
